def extract_nk_values(gemm_map):
    nk_pairs = set()

    for key in gemm_map.keys():
        # 使用正则表达式匹配 M{m}N{n}K{k} 格式
        match = re.match(r'M\d+N(\d+)K(\d+)', key)
        if match:
            n = int(match.group(1))
            k = int(match.group(2))
            nk_pairs.add((n, k))

    return sorted(nk_pairs)


##cache
@functools.lru_cache(maxsize=256)
def AWQ_W4A16_config_cuda(M, N, K, group_size=128):

    cur_config = get_config_v2(M,N,K)
    if cur_config is not None:
        return cur_config

    if "BW" in device_name:
        mode_dict = bw_gemm_templates_prof_best_map
        n_k_list = bw_gemm_n_k_list
    else:
        mode_dict = k100ai_gemm_templates_prof_best_map
        n_k_list = k100ai_n_k_list

    cur_config = mode_dict.get(f"M{M}N{N}K{K}")
    if cur_config is not None:
        return cur_config
    else:
        nearest_m = -1
        if M <=0:
            raise ValueError("M must be greater than 0")
        if M >= 256:
            nearest_m = 256
        else:
            nearest_m = min(m_list, key=lambda x: abs(x - M))
        if(N,K) in n_k_list:
            cur_config = mode_dict.get(f"M{nearest_m}N{N}K{K}")
        if cur_config is not None:
            return cur_config
        else:
            # 寻找n_k_list中与(N,K)最接近的值
            nearest_n_k = min(n_k_list, key=lambda x: abs(x[0] - N) + abs(x[1] - K))

            if M>16 and M<32:
                M_normal="32"
            else:
                M_normal = str(1 << round(math.log2(M)))

            cur_config = mode_dict.get(f"M{M_normal}N{nearest_n_k[0]}K{nearest_n_k[1]}")
            if cur_config is None:
                return "W2Atom1_M32N32K32L1_Bf2_Uf0_Ul1_Gv0"

            L_value = int(re.search(r"L(\d+)", cur_config).group(1))
            if M > 16:
                if K % (group_size*L_value) !=0:
                    cur_config= "W2Atom1_M32N32K32L1_Bf2_Uf0_Ul1_Gv0"
            else:
                K_value = int(re.search(r"K(\d+)L", "W4Atom1_M32N16K128L1_Bf1_Uf0_Ul0_Gv0").group(1))
                if K % (2*group_size*L_value) !=0:
                    cur_config= "W2Atom1_M32N32K32L1_Bf2_Uf0_Ul1_Gv0"
            return cur_config


